const elapsedLabel=(timestamp:string)=>{const seconds=Math.max(0,Math.round((Date.now()-Date.parse(timestamp))/1000));if(seconds<60)return`${seconds}s ago`;const minutes=Math.round(seconds/60);if(minutes<60)return`${minutes}m ago`;const hours=Math.round(minutes/60);return hours<48?`${hours}h ago`:`${Math.round(hours/24)}d ago`;};

type AdminTab = "stream" | "replay" | "permissions";
const ADMIN_TAB_PATHS: Record<AdminTab, string> = {
  stream: "/operations/events",
  replay: "/laboratory/replay",
  permissions: "/operations/events/permissions",
};
const adminTabFromPath = (path: string): AdminTab => {const pathname=path.split(/[?#]/)[0]?.replace(/\/+$/,"")||"/";return pathname==="/laboratory"||pathname.startsWith("/laboratory/replay")||pathname.startsWith("/admin/events/replay")?"replay":pathname.startsWith("/operations/events/permissions")||pathname.startsWith("/admin/events/permissions")?"permissions":"stream";};
const adminTabPath = (tab: AdminTab) => ADMIN_TAB_PATHS[tab];

