  #scenario: ReplayScenarioKey = "complete-application-tour"; #count = 10000; #speed = 250; #stepSize = 100; #playMode:"visible"|"all"="visible"; #playing = false; #timer?: number; #buildMs = 0; #replaySelected = ""; #runnerFollow = true; #runnerPinnedEvent = ""; #replayOutputLimit=12;
